const company = $('Loop Companies').item.json.Company;
const invoiceNumber = $('Format Invoice Number').item.json.invoiceNumber;
const pdfBinary = $('Generate PDF - Gotenberg').item.binary.data;

const fileName = `${company.replace(/ /g, '_')}_INV${invoiceNumber}.pdf`;

return [{
  json: { company, invoiceNumber },
  binary: {
    data: {
      ...pdfBinary,
      fileName: fileName,
      mimeType: 'application/pdf'
    }
  }
}];

const rows = $('Filter Unbilled Loads').item.json.rows;

const groups = {};
for (const row of rows) {
  const driver = row.Driver || 'Unassigned';
  if (!groups[driver]) groups[driver] = [];
  groups[driver].push(row);
}

const driverGroups = Object.keys(groups).map(driver => {
  const rowsForDriver = groups[driver];
  const totalAmount = rowsForDriver.reduce((sum, r) => sum + Number(r.Amount || 0), 0);
  const totalService = rowsForDriver.reduce((sum, r) => sum + Number(r.Service || 0), 0);
  return { driver, lineItems: rowsForDriver, totalAmount, totalService };
});

return driverGroups.map(g => ({ json: g }));

